// Powermove shader layer — GLSL ES 3.0
// uv is 0..1 across the layer. Declare uniforms with @param to get inspector controls.
uniform float uSpeed;   // @param 0.35 0 3
uniform float uScale;   // @param 3.0 0.5 12
uniform vec3  uTint;    // @param #FF6B1A

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * uSpeed;
  float n = fbm(p * uScale + vec2(t, t * 0.6));
  n += 0.35 * fbm(p * uScale * 2.4 - t * 0.4);
  float band = smoothstep(0.28, 0.72, n);
  vec3 col = mix(vec3(0.03, 0.03, 0.04), uTint, band);
  col += pow(band, 6.0) * 0.7;
  float vig = 1.0 - 0.7 * dot(p, p);
  fragColor = vec4(col * vig, 1.0);
}

uniform float uSpeed;  // @param 1.0 0 4
uniform float uCells;  // @param 18.0 2 80
uniform vec3  uInk;    // @param #4C8DFF
void main(){
  vec2 g = uv * uCells;
  vec2 id = floor(g), f = fract(g) - .5;
  float d = sdBox(f, vec2(.34));
  float pulse = smoothstep(.9, 1.0, sin(iTime*uSpeed*2.0 + hash(id)*6.283 + id.x*.2));
  float m = smoothstep(.02, .0, d) * (.12 + pulse);
  vec3 col = vec3(.02) + uInk * m;
  col += uInk * smoothstep(.06,.0,abs(d)) * .25;
  fragColor = vec4(col, 1.0);
}

uniform float uSpeed; // @param .5 0 3
uniform float uWarp;  // @param 2.5 0 8
void main(){
  vec2 p = (uv-.5)*2.0; p.x *= iResolution.x/iResolution.y;
  float t = iTime*uSpeed;
  for(int i=0;i<4;i++){ p += vec2(sin(p.y*3.0+t), cos(p.x*3.0-t))*.18*uWarp*.25; }
  float v = fbm(p*1.6+t*.2);
  vec3 col = palette(v, vec3(.5), vec3(.5), vec3(1.,1.,1.), vec3(0.,.33,.67));
  col = mix(col, vec3(luma(vec3(col))), .35);
  fragColor = vec4(col,1.0);
}

uniform vec3 uA; // @param #FF6B1A
uniform vec3 uB; // @param #120A06
uniform float uAngle; // @param 0.35 0 6.28
void main(){
  vec2 p = uv - .5; p = rot(uAngle) * p;
  float g = smoothstep(-.5,.5,p.y);
  float n = (noise(uv*vec2(600.,600.))-.5)*.012;
  fragColor = vec4(mix(uB,uA,g)+n, 1.0);
}

uniform float uCount; // @param 40 4 200
uniform float uSpeed; // @param .6 0 4
uniform vec3 uCol;    // @param #E8E2CF
void main(){
  float y = fract(uv.y*uCount - iTime*uSpeed);
  float m = smoothstep(.5,.48,abs(y-.5));
  float fade = smoothstep(0.,.4,iProgress)*smoothstep(1.,.7,iProgress);
  fragColor = vec4(uCol*m*fade, m*fade);
}

// Aurora ribbons drifting across a dark night sky.
uniform float uSpeed;  // @param 0.15 0 1
uniform float uCount;  // @param 4 1 8
uniform vec3  uGlow;   // @param #3DFFB0

void main() {
  float aspect = iResolution.x / iResolution.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y);
  float t = iTime * uSpeed;

  // Dark sky gradient
  vec3 col = mix(vec3(0.012, 0.02, 0.05), vec3(0.002, 0.004, 0.015), uv.y);

  // Twinkling stars
  vec2 cell = floor(vec2(uv.x * aspect, uv.y) * 220.0);
  float s = hash(cell);
  float star = step(0.996, s) * (0.55 + 0.45 * sin(iTime * 1.7 + s * 90.0));
  col += vec3(0.8, 0.85, 1.0) * star * 0.5 * smoothstep(0.05, 0.5, uv.y);

  // Aurora ribbons
  vec3 topTint = mix(uGlow, vec3(0.55, 0.2, 0.9), 0.6);
  vec3 aur = vec3(0.0);
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float on = clamp(uCount - fi, 0.0, 1.0); // fractional count fades ribbons in smoothly
    if (on <= 0.0) break;
    float seed = hash1(fi + 1.3);
    float dir = mod(fi, 2.0) < 1.0 ? 1.0 : -1.0;
    float drift = t * (0.6 + 0.5 * seed) * dir;
    float x = p.x;

    float base = 0.3 + 0.45 * hash1(fi * 3.7 + 0.2);
    float y = base
            + 0.12 * sin(x * (1.2 + seed) + drift * 1.3 + seed * 6.28)
            + 0.18 * (fbm(vec2(x * 0.8 + drift, fi * 4.1 + t * 0.3)) - 0.5);

    float d = p.y - y;
    float below = exp(-max(-d, 0.0) * 60.0);            // crisp lower edge
    float above = exp(-max(d, 0.0) * (5.0 + 4.0 * seed)); // long upward curtain
    float curtain = below * above;

    float rays = 0.55 + 0.45 * noise(vec2(x * 28.0 + drift * 3.0, fi * 7.0));
    rays *= 0.7 + 0.3 * noise(vec2(x * 90.0, t + fi));
    float fadeX = 0.35 + 0.65 * fbm(vec2(x * 1.5 - drift * 0.7, fi * 2.3));

    float a = curtain * rays * fadeX * on;
    vec3 c = mix(uGlow, topTint, smoothstep(0.0, 0.25, d));
    aur += c * a * 0.55;
  }

  // Soft glow tonemap so overlapping ribbons bloom instead of clipping
  col += 1.0 - exp(-aur * 1.6);
  fragColor = vec4(col, 1.0);
}

// Countdown ring — empties clockwise from 12 o'clock across the layer's duration.
// Transparent background. Arc length = 1 - iProgress.
uniform vec3  uColor;        // @param #FFFFFF
uniform float uThickness;    // @param 0.06 0.005 0.3
uniform float uRadius;       // @param 0.38 0.05 0.5
uniform float uTrackOpacity; // @param 0.15 0 1
uniform bool  uRoundCaps;    // @param true

const float TAU = 6.28318530718;

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float aa = 1.0 / iResolution.y;
  float r = uRadius;
  float hw = uThickness * 0.5;
  float len = length(p);

  // Full ring SDF (track)
  float dRing = abs(len - r) - hw;
  float track = 1.0 - smoothstep(-aa, aa, dRing);

  // Angle from top, clockwise, 0..1
  float f = fract(atan(p.x, p.y) / TAU + 1.0);
  float remain = clamp(1.0 - iProgress, 0.0, 1.0);

  float arc;
  if (uRoundCaps) {
    float dArc;
    if (f <= remain) {
      dArc = dRing;
    } else {
      vec2 e0 = vec2(0.0, r);
      float ea = remain * TAU;
      vec2 e1 = vec2(sin(ea), cos(ea)) * r;
      dArc = min(length(p - e0), length(p - e1)) - hw;
    }
    arc = 1.0 - smoothstep(-aa, aa, dArc);
  } else {
    float s = (f <= remain) ? min(f, remain - f) * TAU * len : -1.0;
    arc = track * clamp(s / aa + 0.5, 0.0, 1.0);
  }
  arc *= step(1e-4, remain);

  float a = max(arc, track * uTrackOpacity);
  fragColor = vec4(uColor, a);
}

// Cursor glow over a subtle gradient — Shadertoy style.
// iMouse is read in pixels (Shadertoy convention); values in 0..1 are treated as uv.
// With no mouse input (0,0), the glow drifts on a slow Lissajous path so renders stay alive.
uniform float uRadius;     // @param 0.22 0.02 1.0
uniform float uIntensity;  // @param 1.0 0 3
uniform float uFalloff;    // @param 2.2 0.5 6
uniform float uDrift;      // @param 0.25 0 2
uniform vec3  uGlow;       // @param #FF8A3D
uniform vec3  uTop;        // @param #141826
uniform vec3  uBottom;     // @param #07080D
uniform bool  uFollowMouse; // @param true

void main() {
  float aspect = iResolution.x / max(iResolution.y, 1.0);
  vec2 asp = vec2(aspect, 1.0);

  // Subtle diagonal gradient with soft noise breathing and dithering against banding.
  float g = clamp(uv.y * 0.85 + uv.x * 0.15, 0.0, 1.0);
  vec3 col = mix(uBottom, uTop, smoothstep(0.0, 1.0, g));
  col += 0.015 * (fbm(uv * 3.0 * asp + iTime * 0.05) - 0.5);

  // Cursor position in uv space.
  vec2 m = iMouse;
  bool hasMouse = uFollowMouse && (m.x > 0.0 || m.y > 0.0);
  if (hasMouse && (m.x > 1.0 || m.y > 1.0)) m /= max(iResolution, vec2(1.0));
  float t = iTime * uDrift;
  vec2 drift = vec2(0.5 + 0.28 * sin(t * 1.3), 0.5 + 0.22 * sin(t * 1.9 + 1.2));
  vec2 c = hasMouse ? m : drift;

  // Glow: soft core + wide halo, aspect-correct.
  float d = length((uv - c) * asp);
  float r = max(uRadius, 1e-3);
  float halo = 1.0 / (1.0 + pow(d / r, uFalloff) * 4.0);
  float core = exp(-pow(d / (r * 0.18), 2.0));
  float pulse = 0.94 + 0.06 * sin(iTime * 2.0);

  vec3 glow = uGlow * halo * 0.85 + mix(uGlow, vec3(1.0), 0.6) * core * 0.6;
  col += glow * uIntensity * pulse;

  // Gentle vignette + tonemap + dither.
  vec2 q = (uv - 0.5) * asp;
  col *= 1.0 - 0.35 * dot(q, q);
  col = col / (1.0 + col * 0.35);
  col += (hash(uv * iResolution + fract(iTime)) - 0.5) / 255.0;

  fragColor = vec4(col, 1.0);
}

// Noise dissolve — warm gradient burns away with a glowing edge over the layer's progress.
uniform vec3  uColorTop;   // @param #FFB347
uniform vec3  uColorBot;   // @param #E2412A
uniform vec3  uEdgeColor;  // @param #FFC45A
uniform vec3  uCharColor;  // @param #2A0E05
uniform float uScale;      // @param 4.0 0.5 16
uniform float uEdge;       // @param 0.08 0.005 0.3
uniform float uGlow;       // @param 2.5 0 8
uniform float uDrift;      // @param 0.08 0 1

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);

  // Dissolve noise, remapped to roughly 0..1
  float n = fbm(p * uScale + vec2(iTime * uDrift, -iTime * uDrift * 0.7));
  n = 0.75 * n + 0.25 * fbm(p * uScale * 3.1 + 7.3);
  n = clamp((n - 0.2) / 0.6, 0.0, 1.0);

  // Threshold sweeps so progress 0 = intact, progress 1 = fully gone
  float e = max(uEdge, 1e-3);
  float thr = mix(-e - 0.01, 1.01, clamp(iProgress, 0.0, 1.0));
  if (n < thr) discard;

  // Edge factor: 1 at the burn front, 0 once uEdge away from it
  float edge = 1.0 - smoothstep(0.0, e, n - thr);

  // Warm gradient with a gentle sheen
  float g = clamp(uv.y + 0.08 * sin(uv.x * 6.2831 + iTime * 0.5), 0.0, 1.0);
  vec3 col = mix(uColorBot, uColorTop, g);

  // Char band then glowing rim
  col = mix(col, uCharColor, smoothstep(0.0, 0.6, edge));
  col += uEdgeColor * uGlow * pow(edge, 3.0);

  fragColor = vec4(col, 1.0);
}

// Transparent vignette overlay — clear centre, darkening toward the edges.
uniform float uStrength; // @param 0.75 0 1
uniform float uRadius;   // @param 0.45 0 1.5
uniform float uSoftness; // @param 0.5 0.01 1.5
uniform vec3  uColor;    // @param #000000

void main() {
  // Aspect-corrected distance from centre (short axis spans -0.5..0.5)
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float d = length(p);

  // Fully transparent inside the radius: bail out early
  if (d <= uRadius) {
    fragColor = vec4(0.0);
    return;
  }

  float t = smoothstep(uRadius, uRadius + uSoftness, d);
  float a = clamp(t * uStrength, 0.0, 1.0);
  // Premultiplied colour (default black is also correct for straight alpha)
  fragColor = vec4(uColor * a, a);
}

// Sky gradient with samplerCube environment reflections mixed in at 20%.
// uEnvMap is not an @param: nothing is bound yet, so it samples black.
uniform vec3  uZenith;    // @param #1E4FA8
uniform vec3  uHorizon;   // @param #9CC8F0
uniform vec3  uGround;    // @param #3A3F4A
uniform vec3  uSunColor;  // @param #FFE2B0
uniform float uSunHeight; // @param 0.25 -0.2 1
uniform float uSunX;      // @param 0.3 -1 1
uniform float uSunSize;   // @param 0.04 0.005 0.2
uniform float uHorizonY;  // @param 0.45 0 1
uniform float uEnvMix;    // @param 0.2 0 1
uniform float uFov;       // @param 1.2 0.3 2.5
uniform samplerCube uEnvMap;

void main() {
  float aspect = iResolution.x / iResolution.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y - uHorizonY);

  // View ray for this pixel (camera looks toward -Z, Y up).
  vec3 dir = normalize(vec3(p.x * uFov, p.y * uFov, -1.0));

  // Sky gradient: horizon -> zenith above, horizon -> ground below.
  float h = dir.y;
  vec3 sky = mix(uHorizon, uZenith, pow(clamp(h, 0.0, 1.0), 0.6));
  vec3 below = mix(uHorizon, uGround, smoothstep(0.0, 0.35, -h));
  vec3 col = h >= 0.0 ? sky : below;

  // Horizon haze band.
  col += uHorizon * 0.15 * exp(-abs(h) * 18.0);

  // Sun disc + glow.
  vec3 sunDir = normalize(vec3(uSunX, uSunHeight, -1.0));
  float sd = max(dot(dir, sunDir), 0.0);
  float disc = smoothstep(1.0 - uSunSize * 0.05, 1.0 - uSunSize * 0.04, sd);
  col += uSunColor * (disc * 2.0 + pow(sd, 64.0) * 0.6 + pow(sd, 8.0) * 0.15);

  // Environment reflection: mirror rays below the horizon about the ground plane.
  vec3 rdir = h >= 0.0 ? dir : reflect(dir, vec3(0.0, 1.0, 0.0));
  vec3 env = textureLod(uEnvMap, rdir, 0.0).rgb;
  col = mix(col, env, clamp(uEnvMix, 0.0, 1.0));

  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

// Old film flicker — brightness steps randomly once per frame, dust re-rolls every frame.
uniform float uFlicker;   // @param 0.25 0 1
uniform float uDust;      // @param 0.5 0 1
uniform float uDustSize;  // @param 1.0 0.2 4
uniform float uScratches; // @param 0.35 0 1
uniform float uGrain;     // @param 0.08 0 0.5
uniform float uVignette;  // @param 0.6 0 1.5
uniform vec3  uTint;      // @param #CDB892

void main() {
  float aspect = iResolution.x / iResolution.y;
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  float f = float(iFrame);

  // Base film image: soft sepia exposure with a slow, faint density variation
  float dens = 0.75 + 0.25 * fbm(p * 1.8 + 3.7);
  vec3 col = uTint * dens;

  // Per-frame flicker: one random value per frame, no interpolation
  float r1 = hash1(f * 0.7313 + 1.17);
  float r2 = hash1(f * 1.9177 + 4.31);
  float flick = 1.0 + ((r1 + r2) - 1.0) * uFlicker;
  col *= flick;

  // Dust specks: new random set every frame
  float px = 1.0 / iResolution.y;
  float dust = 0.0;
  for (int i = 0; i < 32; i++) {
    float fi = float(i);
    float seed = f * 17.13 + fi * 3.71;
    if (hash1(seed + 0.5) > uDust) continue;
    vec2 c = (vec2(hash1(seed + 1.1), hash1(seed + 2.3)) - 0.5) * vec2(aspect, 1.0);
    float rad = (1.5 + 5.0 * pow(hash1(seed + 3.7), 3.0)) * px * uDustSize;
    // slightly irregular shape
    vec2 d = p - c;
    d *= vec2(1.0, 0.6 + 0.8 * hash1(seed + 5.9));
    float irr = 1.0 + 0.4 * (noise(d / max(rad, 1e-5) * 1.5 + seed) - 0.5);
    float speck = 1.0 - smoothstep(rad * 0.6 * irr, rad * irr, length(d));
    // mostly dark specks, occasional bright ones (dirt on negative)
    float sgn = hash1(seed + 7.7) < 0.8 ? -1.0 : 1.0;
    dust += sgn * speck * (0.5 + 0.5 * hash1(seed + 8.3));
  }
  col += dust * 0.7 * vec3(1.0);

  // Vertical scratches that jump per frame
  for (int i = 0; i < 3; i++) {
    float seed = f * 5.31 + float(i) * 11.7;
    if (hash1(seed) > uScratches) continue;
    float x = hash1(seed + 1.3);
    float w = (0.6 + 1.2 * hash1(seed + 2.1)) / iResolution.x;
    float wob = 0.002 * sin(uv.y * 9.0 + seed);
    float line = 1.0 - smoothstep(0.0, w, abs(uv.x - x - wob));
    float fade = smoothstep(0.0, 0.3, noise(vec2(uv.y * 6.0, seed)));
    col += line * fade * 0.35 * (hash1(seed + 4.4) < 0.5 ? -1.0 : 1.0);
  }

  // Grain, re-rolled each frame
  float g = hash(floor(uv * iResolution) + vec2(f * 13.7, f * 7.1)) - 0.5;
  col += g * uGrain;

  // Vignette
  float vig = 1.0 - uVignette * dot(p, p) * 1.2;
  col *= clamp(vig, 0.0, 1.0);

  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

// Digital glitch blocks over a gradient.
// Blocks shift horizontally and re-randomize uRate times per second.
uniform float uIntensity;  // @param 0.6 0 1
uniform float uRate;       // @param 8.0 1 30
uniform float uBlockSize;  // @param 0.08 0.02 0.3
uniform float uRGBSplit;   // @param 0.5 0 1
uniform vec3  uColorA;     // @param #1A1F6B
uniform vec3  uColorB;     // @param #FF4D8D

vec3 grad(vec2 q) {
  q.x = fract(q.x);
  float t = clamp(q.x * 0.75 + q.y * 0.25, 0.0, 1.0);
  vec3 c = mix(uColorA, uColorB, smoothstep(0.0, 1.0, t));
  c += 0.06 * (1.0 - q.y);
  return c;
}

// Returns horizontal shift and an "active" mask for one block layer.
vec2 blockLayer(vec2 q, float size, float stepId, float seed) {
  float rows = 1.0 / size;
  float ry = floor(q.y * rows);
  float rowR = hash(vec2(ry + seed, stepId));
  float cols = rows * 0.35;
  float cx = floor(q.x * cols + hash(vec2(ry, stepId + seed + 3.0)) * 4.0);
  float cellR = hash(vec2(cx + seed * 2.0, ry + stepId * 7.13));
  float active = step(1.0 - uIntensity * 0.65, rowR) * step(0.4, cellR);
  float shift = (hash(vec2(ry + seed, stepId + 1.7)) - 0.5) * 0.45;
  return vec2(shift * active, active);
}

void main() {
  float stepId = floor(iTime * uRate);
  vec2 q = uv;

  vec2 a = blockLayer(q, uBlockSize, stepId, 0.0);
  vec2 b = blockLayer(q, uBlockSize * 2.7, stepId + 13.0, 41.0);
  float active = max(a.y, b.y);
  float shift = (a.x + b.x * 0.6) * uIntensity;
  q.x += shift;

  float split = uRGBSplit * 0.02 * uIntensity * active
              * (0.5 + hash(vec2(stepId, floor(uv.y / uBlockSize))));
  vec3 col;
  col.r = grad(q + vec2(split, 0.0)).r;
  col.g = grad(q).g;
  col.b = grad(q - vec2(split, 0.0)).b;

  // Occasional block treatments: invert or posterize.
  float fx = hash(vec2(floor(uv.y / uBlockSize), stepId + 5.0));
  if (active > 0.5 && fx > 0.88) col = 1.0 - col;
  else if (active > 0.5 && fx > 0.72) col = floor(col * 4.0) / 4.0;

  // Thin bright tear lines.
  float lineR = hash(vec2(floor(uv.y * iResolution.y / 2.0), stepId));
  col += step(1.0 - 0.015 * uIntensity, lineR) * 0.5;

  // Faint scanlines.
  col *= 1.0 - 0.06 * uIntensity * step(0.5, fract(uv.y * iResolution.y * 0.5));

  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

// Concentric rings pulsing outward.
// Pulse phase uses iGlobalTime (comp clock) so it stays in sync wherever the layer starts.
// Fade-in uses iTime (layer-local) so it begins when the layer begins.
uniform float uSpeed;     // @param 0.5 0 3
uniform float uDensity;   // @param 8.0 1 30
uniform float uWidth;     // @param 0.18 0.02 0.5
uniform float uFadeIn;    // @param 1.0 0 5
uniform vec3  uRingColor; // @param #FF6B1A
uniform vec3  uBgColor;   // @param #08080B

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float r = length(p);

  // Comp-synced phase: rings travel outward
  float phase = r * uDensity - iGlobalTime * uSpeed * uDensity * 0.25;
  float f = fract(phase);
  float d = min(f, 1.0 - f);                       // distance to ring center (0..0.5)
  float aa = fwidth(phase) * 1.5;
  float ring = 1.0 - smoothstep(uWidth * 0.5 - aa, uWidth * 0.5 + aa, d);
  float glow = exp(-d * 14.0) * 0.35;

  // Rings soften toward the edge
  float falloff = 1.0 - smoothstep(0.15, 0.85, r);

  // Layer-local fade-in
  float fade = uFadeIn > 0.0 ? smoothstep(0.0, 1.0, clamp(iTime / uFadeIn, 0.0, 1.0)) : 1.0;

  float k = (ring + glow) * falloff * fade;
  vec3 col = mix(uBgColor, uRingColor, clamp(k, 0.0, 1.0));
  col += uRingColor * pow(ring * falloff, 4.0) * 0.25 * fade;
  fragColor = vec4(col, 1.0);
}

// Full-frame rainbow with time-swept hue, saturation control,
// and a luminance-desaturated bottom third.
uniform float uSpeed;       // @param 0.15 0 2
uniform float uBands;       // @param 1.0 0.25 6
uniform float uSaturation;  // @param 1.0 0 1
uniform float uBottomDesat; // @param 1.0 0 1
uniform float uEdgeSoft;    // @param 0.02 0 0.2

void main() {
  // Diagonal rainbow across the full frame, hue sweeps over time
  float aspect = iResolution.x / iResolution.y;
  float h = fract((uv.x * aspect + uv.y * 0.35) / aspect * uBands + iTime * uSpeed);
  vec3 col = hsv2rgb(vec3(h, clamp(uSaturation, 0.0, 1.0), 1.0));

  // Bottom third (uv.y < 1/3): mix toward luminance gray
  float edge = 1.0 / 3.0;
  float soft = max(uEdgeSoft, 1e-4);
  float bottom = 1.0 - smoothstep(edge - soft, edge + soft, uv.y);
  vec3 gray = vec3(luma(col));
  col = mix(col, gray, bottom * clamp(uBottomDesat, 0.0, 1.0));

  fragColor = vec4(col, 1.0);
}

// Kaleidoscope — mirrored wedge symmetry with slow rotation.
// Segments snaps to 3, 4, 6 or 8 (5 -> 6, 7 -> 8).
uniform float uSegments;  // @param 6 3 8
uniform float uRotSpeed;  // @param 0.08 -1 1
uniform float uZoom;      // @param 2.5 0.5 8
uniform float uFlow;      // @param 0.15 0 1
uniform vec3  uColorA;    // @param #FF6B1A
uniform vec3  uColorB;    // @param #1AB8FF

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);

  int s = int(floor(uSegments + 0.5));
  float n;
  switch (s) {
    case 3: n = 3.0; break;
    case 4: n = 4.0; break;
    case 5:
    case 6: n = 6.0; break;
    case 7:
    case 8: n = 8.0; break;
    default: n = 6.0; break;
  }

  // slow rotation of the whole kaleidoscope
  p = rot(iTime * uRotSpeed) * p;

  float r = length(p);
  float a = atan(p.y, p.x);
  float seg = 6.28318530718 / n;
  a = mod(a, seg);
  a = abs(a - seg * 0.5);           // mirror within wedge
  vec2 q = vec2(cos(a), sin(a)) * r;

  float t = iTime * uFlow;
  vec2 k = q * uZoom;
  float v = fbm(k + vec2(t, -0.7 * t));
  v += 0.5 * fbm(k * 2.3 + v * 1.5 - t * 0.5);
  v /= 1.5;

  float rings = sin(12.0 * r - iTime * 0.6 + v * 7.0) * 0.5 + 0.5;
  float facet = smoothstep(0.02, 0.0, abs(a - seg * 0.5) * r) * 0.25; // soft seam glow

  vec3 col = mix(uColorA, uColorB, smoothstep(0.3, 0.7, v));
  col *= 0.35 + 0.85 * rings;
  col += pow(rings * v, 3.0) * 0.6 + facet;

  float vig = 1.0 - 0.6 * dot(p, p);
  fragColor = vec4(clamp(col * vig, 0.0, 1.0), 1.0);
}

// Lava lamp — warm metaballs rising slowly over a lit background.
uniform vec3  uBlob;        // @param #FF5A1F
uniform vec3  uBackground;  // @param #1C0716
uniform float uSpeed;       // @param 0.3 0 2
uniform float uSize;        // @param 1.0 0.5 1.8

void main() {
  float asp = iResolution.x / iResolution.y;
  vec2 p = (uv - 0.5) * vec2(asp, 1.0);
  float t = iTime * uSpeed;

  // Gentle wobble of the whole wax so blobs don't look rigid.
  vec2 q = p + 0.03 * vec2(noise(p * 3.0 + t * 0.5) - 0.5, noise(p * 3.0 - t * 0.4 + 7.0) - 0.5);

  float field = 0.0;
  for (int i = 0; i < 9; i++) {
    float fi = float(i);
    float h  = hash1(fi + 1.37);
    float h2 = hash1(fi * 3.71 + 0.53);
    float r  = (0.09 + 0.08 * h2) * uSize;
    // Slow upward travel; spawn/despawn happens off-screen.
    float cyc = fract(t * (0.05 + 0.045 * h) + h2);
    float y = mix(-0.5 - r * 2.2, 0.5 + r * 2.2, cyc);
    float x = (h - 0.5) * asp * 0.75 + 0.07 * sin(t * 0.6 + fi * 2.1 + y * 2.5);
    vec2 d = q - vec2(x, y);
    d *= vec2(1.0 + 0.12 * sin(t * 0.9 + fi), 1.0 - 0.1 * sin(t * 0.9 + fi)); // squash/stretch
    field += r * r / (dot(d, d) + 1e-4);
  }
  // Molten pool at the bottom and a thin cap at the top, like a real lamp.
  float pool = q.y + 0.5 + 0.02 * sin(q.x * 9.0 + t * 1.3);
  field += 0.010 / max(pool * pool, 1e-4) * 0.5 + 0.004 / max(pow(0.52 - q.y, 2.0), 1e-4) * 0.3;

  float w = max(fwidth(field), 0.01);
  float m = smoothstep(1.0 - w, 1.0 + w, field);

  // Background: warmer near the bulb at the bottom, glow halo around wax.
  vec3 bg = uBackground * (1.25 - 0.65 * uv.y);
  bg += uBlob * 0.28 * smoothstep(0.25, 1.0, field) * (1.0 - m);
  bg += uBlob * 0.12 * exp(-6.0 * (uv.y)) ;

  // Wax shading: dark rim, hot luminous core, soft specular.
  float inner = clamp((field - 1.0) / 2.5, 0.0, 1.0);
  vec3 wax = uBlob * (0.55 + 0.75 * sqrt(inner));
  wax = mix(wax, vec3(1.0, 0.86, 0.55), 0.3 * inner * inner);
  wax += 0.08 * smoothstep(0.0, 0.5, inner) * (0.5 - uv.y + 0.5) * uBlob;

  vec3 col = mix(bg, wax, m);
  float vig = 1.0 - 0.55 * dot(p * vec2(0.8, 1.0), p * vec2(0.8, 1.0));
  col *= vig;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

// Topographic map: contour lines over fbm terrain.
// Lines are anti-aliased in screen space via fwidth(), so they stay
// uLineWidth pixels thick (default 1px) at any layer resolution.
uniform float uScale;      // @param 2.5 0.5 10
uniform float uLevels;     // @param 28 4 100
uniform float uSpeed;      // @param 0.04 0 1
uniform float uLineWidth;  // @param 1.0 0.5 3
uniform float uIndexEvery; // @param 5 0 10
uniform float uLineAlpha;  // @param 0.55 0 1
uniform float uTintAmount; // @param 0.35 0 1
uniform vec3  uPaper;      // @param #EFE6D2
uniform vec3  uInk;        // @param #6B4A2B
uniform vec3  uLowTint;    // @param #B9D3A8
uniform vec3  uHighTint;   // @param #E2C49A

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * uSpeed;

  // Terrain height: broad landforms + detail
  float h = 0.65 * fbm(p * uScale + vec2(t, -t * 0.7))
          + 0.35 * fbm(p * uScale * 0.45 + vec2(-3.7, 1.9) - t * 0.3);

  // Contour field
  float v  = h * uLevels;
  float fw = max(fwidth(v), 1e-5);
  float d  = abs(fract(v + 0.5) - 0.5) / fw;          // distance to nearest contour, in pixels
  float line = clamp(0.5 * uLineWidth - d + 0.5, 0.0, 1.0); // pixel coverage

  // Index contours (every Nth level) drawn darker, same 1px thickness
  float alpha = uLineAlpha;
  if (uIndexEvery >= 1.0) {
    float idx = mod(floor(v + 0.5), floor(uIndexEvery));
    if (idx < 0.5) alpha = 1.0;
  }

  // Hypsometric paper tint
  float e = smoothstep(0.25, 0.75, h);
  vec3 tint = mix(uLowTint, uHighTint, e);
  vec3 col = mix(uPaper, uPaper * tint * 1.08, uTintAmount);

  col = mix(col, uInk, line * alpha);
  fragColor = vec4(col, 1.0);
}

// Infinite tunnel — cosine palette, slow rotation
uniform float uSpeed;    // @param 0.6 0 3
uniform float uRotate;   // @param 0.08 -1 1
uniform float uDensity;  // @param 6.0 1 20
uniform float uSegments; // @param 8.0 2 24
uniform float uGlow;     // @param 1.0 0 3

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  p = rot(iTime * uRotate) * p;

  float r = max(length(p), 1e-3);
  float a = atan(p.y, p.x) / 6.28318;           // -0.5..0.5
  float z = 0.3 / r + iTime * uSpeed;           // depth along the tunnel

  float seg = floor(uSegments + 0.5);           // integer keeps the seam invisible
  float ringWave = cos(6.28318 * z * uDensity * 0.25);
  float segWave  = cos(6.28318 * a * seg);
  float tiles = 0.55 + 0.45 * ringWave * segWave;

  // thin bright seams between tiles
  float ringLine = smoothstep(0.92, 1.0, abs(ringWave));
  float segLine  = smoothstep(0.96, 1.0, abs(segWave));
  float lines = max(ringLine, segLine);

  vec3 col = palette(z * 0.12 + 0.08 * cos(6.28318 * a * 3.0),
                     vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.0, 0.33, 0.67));
  col *= tiles;
  col += lines * 0.35 * col;

  // depth fog toward the vanishing point, plus a soft core glow
  float fog = smoothstep(0.0, 0.35, r);
  col *= fog;
  col += uGlow * 0.025 / r * palette(z * 0.12 + 0.5,
                     vec3(0.5), vec3(0.5), vec3(1.0), vec3(0.0, 0.33, 0.67));

  col = 1.0 - exp(-col * 1.4);                  // gentle tone map
  float vig = 1.0 - 0.35 * dot(p, p);
  fragColor = vec4(col * vig, 1.0);
}

// Pixel-perfect checkerboard: each square is exactly uSquarePx layer pixels.
// Every 4th square along each row/column (diagonal cadence) is highlighted.
uniform int   uSquarePx;   // @param 8 1 256
uniform vec3  uColorA;     // @param #1A1A1E
uniform vec3  uColorB;     // @param #E6E6E6
uniform vec3  uHighlight;  // @param #FF6B1A

void main() {
  int n = max(uSquarePx, 1);
  // Integer pixel coordinate within the layer (pixel centers -> exact ints).
  ivec2 px = ivec2(floor(uv * iResolution));
  // Flip Y so square 0,0 is anchored at the top-left of the layer.
  px.y = int(iResolution.y) - 1 - px.y;
  ivec2 cell = px / n;  // px is non-negative, so integer division == floor

  int parity = (cell.x + cell.y) & 1;
  vec3 col = parity == 0 ? uColorA : uColorB;

  // Every 4th square: walking along any row or column, squares 0,4,8,... highlight.
  if (((cell.x + cell.y) & 3) == 0) col = uHighlight;

  fragColor = vec4(col, 1.0);
}

// Loading bar — fills left to right over the layer's duration.
// Everything outside the bar is fully transparent.
uniform float uHeight;     // @param 6 1 40
uniform float uMargin;     // @param 0 0 200
uniform float uBottom;     // @param 0 0 200
uniform vec3  uColor;      // @param #FFFFFF
uniform vec3  uTrackColor; // @param #FFFFFF
uniform float uTrackAlpha; // @param 0.2 0 1
uniform float uOpacity;    // @param 1 0 1

void main() {
  vec2 px = uv * iResolution;              // pixel coords, origin bottom-left
  float x0 = uMargin;
  float x1 = iResolution.x - uMargin;
  float y0 = uBottom;
  float y1 = uBottom + uHeight;

  // Antialiased coverage of the track rectangle
  float inX = smoothstep(x0 - 0.5, x0 + 0.5, px.x) * (1.0 - smoothstep(x1 - 0.5, x1 + 0.5, px.x));
  float inY = smoothstep(y0 - 0.5, y0 + 0.5, px.y) * (1.0 - smoothstep(y1 - 0.5, y1 + 0.5, px.y));
  float track = inX * inY;

  // Filled portion up to the progress edge
  float edge = mix(x0, x1, clamp(iProgress, 0.0, 1.0));
  float fill = track * (1.0 - smoothstep(edge - 0.5, edge + 0.5, px.x));

  float aTrack = track * uTrackAlpha * (1.0 - fill);
  float a = (fill + aTrack) * uOpacity;
  vec3 col = (uColor * fill + uTrackColor * aTrack) * uOpacity; // premultiplied

  fragColor = vec4(col, a);
}

// Raymarched metaball blob — slow morph, key + rim lighting
uniform float uSpeed;     // @param 0.4 0 3
uniform float uBlend;     // @param 0.45 0.05 1.5
uniform float uSize;      // @param 0.42 0.15 0.8
uniform vec3  uBase;      // @param #3A2A8C
uniform vec3  uKey;       // @param #FFE2C0
uniform float uKeyGain;   // @param 1.2 0 3
uniform vec3  uRim;       // @param #3FD8FF
uniform float uRimGain;   // @param 1.4 0 4
uniform float uRimPower;  // @param 3.0 0.5 8
uniform vec3  uBg;        // @param #07070C

struct Hit {
  bool  hit;
  float t;
  vec3  pos;
  int   steps;
};

float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

float map(vec3 q) {
  float t = iTime * uSpeed;
  float d = 1e5;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    vec3 c = vec3(
      sin(t * (0.70 + 0.13 * fi) + fi * 1.7),
      cos(t * (0.50 + 0.11 * fi) + fi * 2.3),
      sin(t * (0.60 + 0.09 * fi) + fi * 0.9)
    ) * vec3(0.7, 0.5, 0.5);
    float r = uSize + 0.08 * sin(t * 1.3 + fi * 2.1);
    d = smin(d, length(q - c) - r, uBlend);
  }
  return d;
}

vec3 calcNormal(vec3 q) {
  const vec2 e = vec2(1.0, -1.0) * 0.0012;
  return normalize(e.xyy * map(q + e.xyy) + e.yyx * map(q + e.yyx) +
                   e.yxy * map(q + e.yxy) + e.xxx * map(q + e.xxx));
}

Hit march(vec3 ro, vec3 rd) {
  Hit h;
  h.hit = false;
  h.t = 0.0;
  h.pos = ro;
  h.steps = 0;
  for (int i = 0; i < 110; i++) {
    h.pos = ro + rd * h.t;
    float d = map(h.pos);
    h.steps = i;
    if (d < 0.0008 * h.t + 0.0005) { h.hit = true; break; }
    h.t += d * 0.9;
    if (h.t > 12.0) break;
  }
  return h;
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * uSpeed;

  vec3 ro = vec3(0.0, 0.0, 3.6);
  ro.xz *= rot(0.15 * sin(t * 0.3));
  vec3 fw = normalize(-ro);
  vec3 rt = normalize(cross(fw, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(rt, fw);
  vec3 rd = normalize(p.x * rt + p.y * up + 1.6 * fw);

  // Background: soft vertical gradient + faint glow
  vec3 col = uBg * (1.0 + 0.6 * (0.5 - uv.y));
  col += uRim * 0.05 * exp(-3.0 * dot(p, p));

  Hit h = march(ro, rd);
  if (h.hit) {
    vec3 n = calcNormal(h.pos);
    vec3 v = -rd;

    vec3 keyDir = normalize(vec3(0.6, 0.7, 0.55));
    vec3 rimDir = normalize(vec3(-0.7, 0.35, -0.6));

    float diff = max(dot(n, keyDir), 0.0);
    float wrap = max((dot(n, keyDir) + 0.3) / 1.3, 0.0);
    vec3 hv = normalize(keyDir + v);
    float spec = pow(max(dot(n, hv), 0.0), 64.0) * diff;

    float fres = pow(1.0 - max(dot(n, v), 0.0), uRimPower);
    float rimMask = clamp(dot(n, rimDir) + 0.6, 0.0, 1.0);
    float rim = fres * rimMask;

    float ao = clamp(1.0 - float(h.steps) / 110.0, 0.0, 1.0);
    ao = mix(0.55, 1.0, ao);
    float amb = 0.5 + 0.5 * n.y;

    vec3 surf = uBase * (0.12 * amb + 0.9 * wrap * uKey * uKeyGain);
    surf += uKey * spec * uKeyGain * 0.9;
    surf *= ao;
    surf += uRim * rim * uRimGain;

    float fog = exp(-0.04 * h.t * h.t);
    col = mix(col, surf, fog);
  }

  float vig = 1.0 - 0.45 * dot(p, p);
  col *= vig;
  col = col / (1.0 + col);          // tonemap
  col = pow(col, vec3(1.0 / 2.2));  // gamma
  fragColor = vec4(col, 1.0);
}

// CRT test pattern — SMPTE-style color bars, scanlines, subtle vignette.
// Helper functions are compiled at mediump; main() restores highp.
uniform float uBrightness;   // @param 1.0 0 2
uniform float uScanline;     // @param 0.35 0 1
uniform float uScanPixels;   // @param 3.0 1 8
uniform float uVignette;     // @param 0.3 0 1
uniform float uFlicker;      // @param 0.025 0 0.2
uniform float uRoll;         // @param 0.06 0 0.3
uniform float uRollSpeed;    // @param 0.12 0 1

precision mediump float;

// Top band: seven 75% bars
vec3 topBar(float x) {
  float i = clamp(floor(x * 7.0), 0.0, 6.0);
  if (i < 0.5) return vec3(0.75, 0.75, 0.75);
  if (i < 1.5) return vec3(0.75, 0.75, 0.0);
  if (i < 2.5) return vec3(0.0, 0.75, 0.75);
  if (i < 3.5) return vec3(0.0, 0.75, 0.0);
  if (i < 4.5) return vec3(0.75, 0.0, 0.75);
  if (i < 5.5) return vec3(0.75, 0.0, 0.0);
  return vec3(0.0, 0.0, 0.75);
}

// Middle strip: reverse castellations
vec3 midBar(float x) {
  float i = clamp(floor(x * 7.0), 0.0, 6.0);
  if (i < 0.5) return vec3(0.0, 0.0, 0.75);
  if (i < 1.5) return vec3(0.075);
  if (i < 2.5) return vec3(0.75, 0.0, 0.75);
  if (i < 3.5) return vec3(0.075);
  if (i < 4.5) return vec3(0.0, 0.75, 0.75);
  if (i < 5.5) return vec3(0.075);
  return vec3(0.75, 0.75, 0.75);
}

// Bottom: -I, 100% white, +Q, black, PLUGE, black
vec3 lowBar(float x) {
  if (x < 5.0 / 28.0)  return vec3(0.0, 0.13, 0.30);
  if (x < 10.0 / 28.0) return vec3(1.0);
  if (x < 15.0 / 28.0) return vec3(0.20, 0.0, 0.42);
  if (x < 5.0 / 7.0)   return vec3(0.075);
  if (x < 6.0 / 7.0) {
    float k = floor((x - 5.0 / 7.0) * 21.0);
    return vec3(k < 0.5 ? 0.035 : (k < 1.5 ? 0.075 : 0.115));
  }
  return vec3(0.075);
}

vec3 testPattern(vec2 q) {
  // q.y measured from the top of the layer
  if (q.y < 0.67) return topBar(q.x);
  if (q.y < 0.75) return midBar(q.x);
  return lowBar(q.x);
}

// phase is fract(pixelY / linePitch), computed at highp by the caller
float scanlineMask(float phase, float amount) {
  float s = 0.5 + 0.5 * cos(6.28318 * phase);
  return 1.0 - amount * (1.0 - s * s);
}

float vignette(vec2 q, float amount) {
  vec2 d = q - 0.5;
  float r = dot(d, d) * 2.0;
  return 1.0 - amount * smoothstep(0.15, 1.0, r);
}

precision highp float;

void main() {
  vec2 q = vec2(uv.x, 1.0 - uv.y);
  vec3 col = testPattern(q) * uBrightness;

  // Scanlines locked to layer pixels
  float py = uv.y * iResolution.y;
  float phase = fract(py / max(uScanPixels, 1.0));
  col *= scanlineMask(phase, uScanline);

  // Faint rolling refresh band
  float roll = fract(q.y - iTime * uRollSpeed);
  col *= 1.0 + uRoll * smoothstep(0.92, 1.0, roll) * (1.0 - smoothstep(0.0, 0.02, 1.0 - roll) * 0.0);

  // Frame-rate flicker
  col *= 1.0 - uFlicker * hash1(floor(iTime * 30.0));

  col *= vignette(uv, uVignette);
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

// Rounded badge — fill, outline and soft drop shadow on a transparent background.
uniform float uRadius;        // @param 0.45 0 1
uniform float uOutline;       // @param 6 0 40
uniform vec3  uFill;          // @param #FF6B1A
uniform vec3  uOutlineColor;  // @param #FFFFFF
uniform float uShadowOpacity; // @param 0.45 0 1
uniform float uShadowBlur;    // @param 18 0 60
uniform float uShadowOffset;  // @param 8 0 40

void main() {
  vec2 px = uv * iResolution;
  vec2 c = iResolution * 0.5;

  // Leave room around the badge so the shadow is not clipped by the layer edge.
  float margin = min(uShadowBlur * 1.2 + uShadowOffset + 4.0, min(iResolution.x, iResolution.y) * 0.3);
  vec2 hb = max(c - margin, vec2(1.0));
  float r = clamp(uRadius, 0.0, 1.0) * min(hb.x, hb.y);

  // Badge shape (pixel-space SDF, 1px anti-aliasing).
  float d = sdBox(px - c, hb - r) - r;
  float shape = clamp(0.5 - d, 0.0, 1.0);
  float inner = clamp(0.5 - (d + uOutline), 0.0, 1.0);

  // Fill with a subtle top-lit gradient, outline ring around it.
  vec3 fillCol = uFill * (0.9 + 0.15 * uv.y);
  vec3 col = mix(uOutlineColor, fillCol, inner);

  // Soft drop shadow, offset downward.
  float ds = sdBox(px - c + vec2(0.0, uShadowOffset), hb - r) - r;
  float blur = max(uShadowBlur, 0.5);
  float sa = uShadowOpacity * (1.0 - smoothstep(-blur * 0.5, blur, ds));

  // Composite badge over shadow (straight alpha output).
  float a = shape + sa * (1.0 - shape);
  vec3 outCol = a > 0.0 ? (col * shape) / a : vec3(0.0);
  fragColor = vec4(outCol, a);
}

// Starfield flying toward the camera.
// Brightest ("hot") stars are overbright (> 1.0) so a downstream glow/bloom can key on them.
uniform float uSpeed;     // @param 0.12 0 1.5
uniform float uDensity;   // @param 0.55 0.05 1
uniform float uHotRatio;  // @param 0.08 0 0.5
uniform float uHotGain;   // @param 4.0 1 12
uniform float uStreak;    // @param 1.5 0 6
uniform vec3  uTint;      // @param #C6D6FF
uniform vec3  uHotTint;   // @param #FFE6C4
uniform vec3  uBg;        // @param #020309

#define LAYERS 6

vec3 starLayer(vec2 p, vec2 n, float z, float seed, float depth) {
  vec2 q = p * z + seed * vec2(13.17, 7.73);
  vec2 id = floor(q);
  vec2 gv = fract(q) - 0.5;
  float stretch = 1.0 + uStreak * depth * depth * length(p);
  vec3 acc = vec3(0.0);
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 o = vec2(float(x), float(y));
      vec2 cid = id + o + seed;
      if (hash(cid) > uDensity) continue;
      vec2 off = vec2(hash(cid + 3.1), hash(cid + 7.4)) - 0.5;
      vec2 d = gv - o - off * 0.8;
      // elongate along the radial (motion) direction
      float dr = dot(d, n);
      float dt = d.x * n.y - d.y * n.x;
      float r = length(vec2(dr / stretch, dt));
      float b = pow(hash(cid + 11.3), 3.0);
      float hot = step(1.0 - uHotRatio, hash(cid + 19.7));
      float size = mix(0.015, 0.05, b) + 0.03 * hot;
      float core = 1.0 - smoothstep(0.0, size, r);
      float glow = 0.0012 / (r * r + 0.0012);
      float inten = (0.25 + 0.75 * b) * (core + 0.35 * glow);
      inten *= mix(1.0, uHotGain, hot);
      vec3 c = mix(uTint, uHotTint, hot) * mix(0.85, 1.15, hash(cid + 5.5));
      acc += c * inten;
    }
  }
  return acc;
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  vec2 n = p / (length(p) + 1e-4);
  float t = iTime * uSpeed;
  vec3 col = uBg;
  for (int i = 0; i < LAYERS; i++) {
    float k = float(i) / float(LAYERS) + t;
    float depth = fract(k);
    float cycle = floor(k);
    float seed = floor(hash1(float(i) * 7.31 + cycle * 31.7) * 997.0);
    // perspective: world z shrinks linearly → screen positions accelerate outward
    float z = mix(22.0, 0.7, depth);
    float fade = smoothstep(0.0, 0.3, depth) * (1.0 - smoothstep(0.88, 1.0, depth));
    col += starLayer(p, n, z, seed, depth) * fade * (0.35 + 0.9 * depth);
  }
  // intentionally unclamped: hot stars exceed 1.0 for glow pickup
  fragColor = vec4(col, 1.0);
}

// Tile pattern: offset brick tiles with Truchet arcs + bevel, optional uPattern texture per tile.
// uPattern is a plain sampler2D (no @param). If it is unbound/empty, the procedural base shows alone.
uniform sampler2D uPattern;
uniform float uTiles;       // @param 6.0 1 24
uniform float uSpeed;       // @param 0.15 0 2
uniform float uPatternMix;  // @param 0.75 0 1
uniform float uGrout;       // @param 0.05 0 0.3
uniform float uArcWidth;    // @param 0.09 0.01 0.3
uniform vec3  uColorA;      // @param #1E3A5F
uniform vec3  uColorB;      // @param #E8B04A
uniform vec3  uGroutColor;  // @param #0B0C10

void main() {
  float aspect = iResolution.x / iResolution.y;
  vec2 p = uv * vec2(aspect, 1.0) * uTiles;
  p.x += iTime * uSpeed;
  p.x += 0.5 * mod(floor(p.y), 2.0);          // brick offset
  vec2 id = floor(p);
  vec2 f = fract(p);
  float h = hash(id);
  float h2 = hash(id + 17.31);

  // Procedural base: per-tile color + Truchet arcs
  vec3 tileCol = mix(uColorA, uColorB, smoothstep(0.15, 0.95, h) * 0.55);
  vec2 q = f - 0.5;
  if (h2 > 0.5) q.x = -q.x;
  float d = min(abs(length(q - 0.5) - 0.5), abs(length(q + 0.5) - 0.5));
  float aa = fwidth(d) + 1e-4;
  float arc = 1.0 - smoothstep(uArcWidth - aa, uArcWidth + aa, d);
  float glow = exp(-d * 18.0) * 0.25;
  vec3 base = mix(tileCol, uColorB, arc) + uColorB * glow;

  // Optional texture, sampled per tile with continuous gradients (no mip seams)
  vec4 tex = textureGrad(uPattern, f, dFdx(p), dFdy(p));
  vec4 probe = textureLod(uPattern, vec2(0.5), 0.0) + textureLod(uPattern, vec2(0.2, 0.7), 0.0)
             + textureLod(uPattern, vec2(0.8, 0.3), 0.0);
  float hasTex = smoothstep(0.002, 0.02, dot(probe, vec4(1.0)));
  vec3 texCol = tex.rgb * (0.65 + 0.7 * luma(base)) + base * 0.15;
  vec3 col = mix(base, texCol, clamp(uPatternMix * hasTex * tex.a, 0.0, 1.0));

  // Bevel + grout
  vec2 e2 = min(f, 1.0 - f);
  float e = min(e2.x, e2.y);
  float ea = fwidth(e) + 1e-4;
  float tileMask = smoothstep(uGrout - ea, uGrout + ea, e);
  float bevel = 1.0 - smoothstep(uGrout, uGrout + 0.08, e);
  float light = (f.y - f.x) * 0.5;              // light from top-left
  col *= 1.0 + bevel * light * 0.6;
  col *= 0.9 + 0.1 * h;
  col = mix(uGroutColor, col, tileMask);

  vec2 c = uv - 0.5;
  col *= 1.0 - 0.45 * dot(c, c);
  fragColor = vec4(col, 1.0);
}

// Diagonal stripes — angle set by #define, density slider, invert checkbox.
#define STRIPE_ANGLE 45.0   // degrees

uniform float uDensity; // @param 12.0 1 80
uniform bool  uInvert;  // @param false

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float a = radians(STRIPE_ANGLE);
  float d = dot(p, vec2(cos(a), sin(a))) * uDensity;
  float f = fract(d);
  float w = fwidth(d) * 0.75;
  // anti-aliased 50% duty stripe
  float s = smoothstep(0.5 - w, 0.5 + w, f) - smoothstep(1.0 - w, 1.0 + w, f) + smoothstep(-w, w, f) - 1.0;
  s = clamp(s, 0.0, 1.0);
  if (uInvert) s = 1.0 - s;
  vec3 col = vec3(s);
  fragColor = vec4(col, 1.0);
}

// Soft spotlight — Powermove shader layer (GLSL ES 3.0)
// uCenter is in layer uv (0..1). uColor rgba: rgb tint, a = peak intensity.
uniform vec2  uCenter;   // @param 0.5,0.5 0 1
uniform vec4  uColor;    // @param 1.0,0.86,0.62,1.0 0 1
uniform float uFalloff;  // @param 0.35 0.02 1.5
uniform float uExtra;    // reserved for a future control (unannotated, no Inspector UI yet)

void main() {
  float aspect = iResolution.x / max(iResolution.y, 1.0);
  vec2 d = (uv - uCenter) * vec2(aspect, 1.0);
  float r = length(d);
  float f = max(uFalloff, 1e-3);
  // Gaussian-like core with a smooth tail that reaches zero.
  float glow = exp(-(r * r) / (f * f));
  glow *= 1.0 - smoothstep(f * 1.5, f * 3.0, r);
  float a = clamp(glow * uColor.a, 0.0, 1.0);
  // Premultiplied output so the light composites over layers below.
  fragColor = vec4(uColor.rgb * a, a);
}

// Cracked glass — animated Voronoi cells with dark borders
uniform float uScale;   // @param 6.0 1.0 20.0
uniform float uBorder;  // @param 0.04 0.0 0.25
uniform float uSpeed;   // @param 0.4 0.0 3.0
uniform vec3  uTint;    // @param #8FC8E8
uniform vec3  uEdge;    // @param #050608

vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

vec2 cellPoint(vec2 c, float t) {
  vec2 h = hash2(c);
  return 0.5 + 0.4 * sin(t + 6.2831 * h);
}

// Returns distance to nearest cell border; outputs cell id and vector to seed.
float voronoi(vec2 x, float t, out vec2 id, out vec2 toSeed) {
  vec2 n = floor(x);
  vec2 f = fract(x);
  vec2 mg = vec2(0.0);
  vec2 mr = vec2(0.0);
  float md = 8.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 r = g + cellPoint(n + g, t) - f;
      float d = dot(r, r);
      if (d < md) { md = d; mr = r; mg = g; }
    }
  }
  md = 8.0;
  for (int j = -2; j <= 2; j++) {
    for (int i = -2; i <= 2; i++) {
      vec2 g = mg + vec2(float(i), float(j));
      vec2 r = g + cellPoint(n + g, t) - f;
      vec2 dr = r - mr;
      if (dot(dr, dr) > 1e-5) {
        md = min(md, dot(0.5 * (mr + r), normalize(dr)));
      }
    }
  }
  id = n + mg;
  toSeed = mr;
  return md;
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * uSpeed;

  vec2 id, toSeed;
  float d = voronoi(p * uScale, t, id, toSeed);

  // Per-cell glass shard color with faceted lighting
  vec2 h = hash2(id);
  vec3 col = uTint * (0.45 + 0.55 * h.x);
  vec2 dir = normalize(toSeed + 1e-4);
  float facet = dot(dir, normalize(vec2(0.6 + 0.4 * h.y, 0.8)));
  col *= 0.75 + 0.35 * facet;
  col += 0.08 * fbm(p * uScale * 1.5 + id);

  // Bright rim just inside each crack
  float aa = max(fwidth(d), 1e-4);
  float rim = 1.0 - smoothstep(uBorder, uBorder + 0.08, d);
  col += rim * 0.35 * (0.5 + 0.5 * h.y);

  // Dark crack border
  float edge = 1.0 - smoothstep(uBorder - aa, uBorder + aa, d);
  col = mix(col, uEdge, edge);

  float vig = 1.0 - 0.5 * dot(p, p);
  fragColor = vec4(col * vig, 1.0);
}

uniform float uA;
// @param 2 1 4
uniform float uB;

uniform bool uT; // @param TRUE
uniform bool uU; // @param true false
uniform bool uV;
